import type { AnyPlugin } from '../models/config.ts';
import type { AnyRule } from '../models/rule.ts';
import {
  JsonSchemaUtil,
  type JsonSchema,
  type SchemaContext,
  type SchemaRow,
} from '../utils/jsonSchemaUtil.ts';
import { LiteralUtil } from '../utils/literalUtil.ts';
import { MarkdownUtil } from '../utils/markdownUtil.ts';

/** First line of every generated file, so stale generated files can be found and removed. */
export const RULE_DOCS_MARKER = '<!-- Generated by `pilotlint rules docs`. Do not edit. -->';

export interface RuleDocsFile {
  /** Path relative to the output directory. */
  readonly path: string;
  readonly content: string;
}

const fileOf = (plugin: AnyPlugin) => `${plugin.name.replace(/[^\w-]/g, '-')}.md`;

const sortedRules = (plugin: AnyPlugin) =>
  Object.entries(plugin.rules).sort(([a], [b]) => a.localeCompare(b));

const optionsTable = (rows: readonly SchemaRow[], label = 'Option') =>
  MarkdownUtil.table(
    [label, 'Type', 'Default', 'Description'],
    rows.map((row) => [
      MarkdownUtil.code(row.name, true),
      MarkdownUtil.code(row.type, true),
      row.hasDefault
        ? MarkdownUtil.code(LiteralUtil.inline(row.default), true)
        : row.required
          ? 'required'
          : '',
      MarkdownUtil.cell(row.description ?? ''),
    ]),
  );

const optionsSection = (rule: AnyRule, schema: JsonSchema | undefined, context: SchemaContext) => {
  if (!rule.options) {
    return ['### Options', '', 'None.'];
  }
  if (!schema) {
    return ['### Options', '', 'The options schema cannot be shown as JSON Schema.'];
  }
  const rows = JsonSchemaUtil.rowsOf(schema, context);
  const shape = MarkdownUtil.fence('ts', JsonSchemaUtil.declaration(schema, context, 0, true));
  return ['### Options', '', shape, ...(rows.length ? ['', optionsTable(rows)] : [])];
};

const exampleSection = (id: string, rule: AnyRule) => {
  const example = rule.meta.example ?? (rule.options ? undefined : rule.meta.severity);
  if (example === undefined) {
    return [];
  }
  const label = `${LiteralUtil.inline(id)}: `;
  const entry = `  ${label}${LiteralUtil.print(example, 2, label.length)},`;
  return ['', '### Example', '', MarkdownUtil.fence('ts', `rules: {\n${entry}\n},`)];
};

const ruleSection = (plugin: AnyPlugin, key: string, rule: AnyRule, context: SchemaContext) => {
  const id = `${plugin.name}/${key}`;
  const schema = JsonSchemaUtil.fromStandard(rule.options);
  const root = schema ? { ...context, root: schema } : context;
  return [
    `## ${key}`,
    '',
    rule.meta.description,
    '',
    `- **Id:** ${MarkdownUtil.code(id)}`,
    `- **Default level:** ${MarkdownUtil.code(rule.meta.severity)}`,
    ...(rule.meta.docs ? ['', rule.meta.docs.trim()] : []),
    '',
    ...optionsSection(rule, schema, root),
    ...exampleSection(id, rule),
  ];
};

const typesSection = (context: SchemaContext) => {
  const lines: string[] = [];
  const done = new Set<string>();
  // Rendering a type can find more types, so loop until every type is documented.
  for (let pending = [...context.named.keys()]; pending.length;) {
    for (const name of pending) {
      done.add(name);
      const schema = context.named.get(name) ?? {};
      const body = JsonSchemaUtil.declaration(schema, context, 0, true);
      const rows = JsonSchemaUtil.typeRowsOf(schema, context);
      lines.push(
        '',
        `### ${name}`,
        ...(typeof schema.description === 'string' ? ['', schema.description] : []),
        '',
        MarkdownUtil.fence('ts', `type ${name} =${body.startsWith('\n') ? '' : ' '}${body};`),
        ...(rows.length ? ['', optionsTable(rows, 'Field')] : []),
      );
    }
    pending = [...context.named.keys()].filter((name) => !done.has(name));
  }
  return lines.length ? ['', '## Types', '', 'Types used by the options above.', ...lines] : [];
};

const pluginPage = (plugin: AnyPlugin): RuleDocsFile => {
  const context: SchemaContext = { root: {}, named: new Map() };
  const rules = sortedRules(plugin);
  const index = MarkdownUtil.table(
    ['Rule', 'Description', 'Default level'],
    rules.map(([key, rule]) => [
      `[${key}](#${MarkdownUtil.anchor(key)})`,
      MarkdownUtil.cell(rule.meta.description),
      MarkdownUtil.code(rule.meta.severity),
    ]),
  );
  const sections = rules.flatMap(([key, rule]) => ['', ...ruleSection(plugin, key, rule, context)]);
  const lines = [
    RULE_DOCS_MARKER,
    '',
    `# ${plugin.name}`,
    ...(plugin.description ? ['', plugin.description] : []),
    '',
    index,
    ...sections,
    ...typesSection(context),
  ];
  return { path: fileOf(plugin), content: `${lines.join('\n')}\n` };
};

const indexPage = (plugins: readonly AnyPlugin[]): RuleDocsFile => {
  const lines = [RULE_DOCS_MARKER, '', '# Rules'];
  for (const plugin of plugins) {
    const file = fileOf(plugin);
    lines.push('', `## [${plugin.name}](${file})`);
    if (plugin.description) {
      lines.push('', plugin.description);
    }
    lines.push('');
    for (const [key, rule] of sortedRules(plugin)) {
      lines.push(`- [${key}](${file}#${MarkdownUtil.anchor(key)}): ${rule.meta.description}`);
    }
  }
  return { path: 'README.md', content: `${lines.join('\n')}\n` };
};

/** Markdown docs for the rules of these plugins: an index and one page per plugin. */
export function renderRuleDocs(plugins: readonly AnyPlugin[]): RuleDocsFile[] {
  return [indexPage(plugins), ...plugins.map(pluginPage)];
}
